import os
from langchain_core.tools import tool

PAYSLIP_DIR = os.environ.get("PAYSLIP_DIR", "/srv/hr/payslips")


def _read_text(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()


@tool
def get_employee_payslip(payslip_file: str) -> str:
    path = os.path.join(PAYSLIP_DIR, payslip_file)
    if not os.path.isfile(path):
        return "Payslip not found: " + payslip_file
    text = _read_text(path)
    return text.strip()

from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("hr-policies")

POLICY_ROOT = "/opt/hr/policies"


def _load(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


@mcp.tool()
def load_leave_policy_document(document_name: str, max_chars: int = 5000) -> str:
    target = Path(POLICY_ROOT) / document_name
    if not target.exists():
        return "No such policy document."
    content = _load(target)
    if max_chars and len(content) > max_chars:
        content = content[:max_chars] + "..."
    return content

import csv
import json
import os
from agents import function_tool

TIMESHEET_BASE = "/data/payroll/timesheets"


def _sum_hours(path):
    total = 0.0
    count = 0
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            try:
                total += float(row.get("hours", 0) or 0)
                count += 1
            except ValueError:
                continue
    return total, count


@function_tool
def summarize_timesheet_csv(timesheet_path: str) -> str:
    full_path = os.path.join(TIMESHEET_BASE, timesheet_path)
    total, count = _sum_hours(full_path)
    return json.dumps({"file": timesheet_path, "total_hours": total, "entries": count})
